    monkeypatch.setenv('USERPROFILE', str(tmp_path))
    (tmp_path / 'config.toml').mkdir()
    path = '~/config.toml' if home_path else tmp_path / 'config.toml'
    paths = [path, tmp_path / 'missing.toml'] if multiple_files else path

